ruleBookInfo.name:
@js:(function () {
var slug = baseUrl.split('/').pop();
var page = java.ajax('https://baozimh.org/chapterlist/' + slug);
var mm = /data-mid="(\d+)"/.exec(page);
if (!mm) { return ''; }
var raw = java.ajax('https://v2.apikk.top/api/manga/get?mid=' + mm[1] + '&mode=all');
var o = JSON.parse(raw);
var d = (o && o.data) || {};
return d.title || '';
})()

